protected override void OnModelCreating(ModelBuilder modelBuilder)
{
    modelBuilder.Entity<Product>(b =>
    {
        b.ToContainer("Products");

        // EF Core 9 renamed the default discriminator property from "Discriminator" to "$type".
        // Existing 500K documents and direct SQL queries use "Discriminator", so preserve it.
        b.HasDiscriminator<string>("Discriminator");

        // EF Core 9 changed id values from "EntityType|Key" to just "Key".
        // Existing documents have ids like "Product|123", so preserve the old format.
        b.HasRootDiscriminatorInJsonId(true);

        // HasIndex is removed — Cosmos DB indexing is managed via the container's indexing policy,
        // not through EF Core. The previous HasIndex(p => p.Sku) call was silently ignored
        // in EF Core 8 but now throws InvalidOperationException at startup in EF Core 9.
    });
}

